"""Persistent shared JSON cache for public demonstration profiles."""
import json
import os
import tempfile
import time

from app.config import CACHE_PATH, CACHE_TTL


def _read_all():
    """Load the whole cache file, tolerating absence/corruption."""
    try:
        with open(CACHE_PATH, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except (FileNotFoundError, ValueError):
        return {}
    return data if isinstance(data, dict) else {}


def _write_all(data):
    """Atomically persist the cache so a new process can reuse it."""
    directory = os.path.dirname(CACHE_PATH) or "."
    os.makedirs(directory, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=directory, suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(data, fh)
        os.replace(tmp, CACHE_PATH)
    except Exception:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def get_or_load(key, loader, now=None):
    """Return cached JSON for `key` while fresh, else (re)load via `loader`.

    Entries are stored as {key: {stored_at: epoch_seconds, value: profile}}.
    Values are persisted to CACHE_PATH so a freshly started process reuses
    them. A loader returning None (missing profile) is never cached, so a
    404 stays a 404.
    """
    current = time.time() if now is None else now
    store = _read_all()
    entry = store.get(key)
    if isinstance(entry, dict) and "stored_at" in entry and "value" in entry:
        age = current - entry["stored_at"]
        if 0 <= age < CACHE_TTL:
            return entry["value"]

    value = loader()
    if value is None:
        # Do not cache misses; the endpoint still surfaces a 404.
        return None

    store[key] = {"stored_at": current, "value": value}
    _write_all(store)
    return value

