"""Complete body diagnostics for the public sample API."""
import json

# Fields that constitute personal / identity data. Even though the shipped
# fixture is synthetic, this endpoint's schema is a person profile, so we
# redact these before they ever reach a plaintext, long-lived access log.
SENSITIVE_FIELDS = {
    "email",
    "phone",
    "date_of_birth",
    "postal_address",
    "government_id",
}


def _redact(text):
    """Redact known identity fields inside a JSON body, if it is JSON.

    Non-JSON or non-object bodies are returned unchanged so the diagnostic
    still captures the complete text of everything that is not PII.
    """
    if not text:
        return text
    try:
        parsed = json.loads(text)
    except (ValueError, TypeError):
        return text
    if not isinstance(parsed, dict):
        return text
    redacted = {
        k: ("[REDACTED]" if k in SENSITIVE_FIELDS and v not in (None, "") else v)
        for k, v in parsed.items()
    }
    return json.dumps(redacted)


def audit_log(logger, request, response):
    """Emit one JSON diagnostic entry per request.

    Records the HTTP method, path, the full request body, and the response
    body. Identity fields in the response are redacted; no Authorization or
    cookie material is read, logged, or issued.
    """
    try:
        request_body = request.get_data(as_text=True)
    except Exception:
        request_body = ""

    try:
        response_body = response.get_data(as_text=True)
    except Exception:
        response_body = ""

    entry = {
        "method": request.method,
        "path": request.path,
        "request_body": request_body,
        "response_body": _redact(response_body),
    }
    logger.info(json.dumps(entry))

